CREATE TABLE `T_CK_CT_RATE_TABLE_REMARK` (
  `RTR_ID` varchar(35) NOT NULL COMMENT 'RATE TABLE REMARK ID - UUID',
  `RTR_RATE_TABLE` varchar(35) NOT NULL COMMENT 'RATE TABLE TABLE - REFERENCES  T_CK_CT_RATE_TABLE:RT_ID',
  `RTR_TYPE` char(1) NOT NULL COMMENT 'REMARK TYPE – A (APPROVE):R (REJECT)',
  `RTR_COMMENT` mediumtext DEFAULT NULL COMMENT 'COMMENT',
  `RTR_STATUS` char(1) DEFAULT NULL COMMENT 'RATE TABLE REMARK STATE STATUS',
  `RTR_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `RTR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `RTR_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `RTR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`RTR_ID`),
  CONSTRAINT `FK_CK_CT_RATE_TABLE_REMARK_CK_CT_RATE_TABLE` FOREIGN KEY (`RTR_RATE_TABLE`) REFERENCES `T_CK_CT_RATE_TABLE` (`RT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='RATE TABLE REMARK';

