CREATE TABLE `T_CK_MST_CREDIT_UPDATE_STATE` (
  `ST_ID` varchar(35) NOT NULL COMMENT 'CREDIT UPDATE STATE ID - NEW : SUBMITTED : DELETED : APPROVE : REJECTED : ACTIVE',
  `ST_NAME` varchar(100) NOT NULL COMMENT 'CREDIT UPDATE  STATE NAME',
  `ST_DESC` varchar(255) DEFAULT NULL COMMENT 'CREDIT UPDATE STATE DESCRIPTION',
  `ST_DESC_OTH` varchar(512) DEFAULT NULL COMMENT 'CREDIT UPDATE STATE DESCRIPTION OTHER LANGUAGE',
  `ST_STATUS` char(1) DEFAULT NULL COMMENT 'CREDIT UPDATE STATE STATUS',
  `ST_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ST_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ST_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ST_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ST_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CREDIT UPDATE STATE TABLE';

