CREATE TABLE `T_CK_CREDIT_UPDATE` (
  `CRU_ID` varchar(35) NOT NULL COMMENT 'RECORD ID - UUID',
  `CRU_SERVICE_TYPE` varchar(35) DEFAULT NULL COMMENT 'CREDIT SERVICE TYPE - REFERENCES T_CK_MST_CREDIT_UPDATE_STATE:ST_ID',
  `CRU_COMPANY` varchar(35) DEFAULT NULL COMMENT 'CREDIT COMPANY ACCOUNT - REFERENCES T_CORE_ACCN:ACCN_ID',
  `CRU_STATE` varchar(35) DEFAULT NULL COMMENT 'CREDIT STATE - REFERENCES T_CK_MST_CREDIT_STATE:CRST_ID',
  `CRU_AMT` double(15,2) DEFAULT '0.00' COMMENT 'CREDIT AMOUNT',
  `CRU_TXN_CAP` double(15,2) DEFAULT NULL COMMENT 'MONTHLY TRANSACTION CAP',
  `CRU_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY  - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `CRU_DT_START` datetime DEFAULT NULL COMMENT 'CREDIT START DATE TIME',
  `CRU_DT_END` datetime DEFAULT NULL COMMENT 'CREDIT END DATE TIME',
  `CRU_REMARKS` mediumtext COMMENT 'REMARKS FROM REQUESTER',
  `CRU_USR_VERIFY` varchar(35) DEFAULT NULL COMMENT 'CREDIT VERIFIER',
  `CRU_DT_VERIFY` datetime DEFAULT NULL COMMENT 'CREDIT VERIFIED DATE TIME',
  `CRU_USR_APPROVE` varchar(35) DEFAULT NULL COMMENT 'CREDIT APPROVER',
  `CRU_DT_APPROVE` datetime DEFAULT NULL COMMENT 'CREDIT APPROVED DATE TIME',
  `CRU_USR_REJECT` varchar(35) DEFAULT NULL COMMENT 'CREDIT REJECT',
  `CRU_DT_REJECT` datetime DEFAULT NULL COMMENT 'CREDIT REJECT DATE TIME',
  `CRU_APPROVER_REMARKS` mediumtext COMMENT 'REMARKS FOR CREDIT APPROVAL OR REJECTION',
  `CRU_STATUS` char(1) DEFAULT NULL COMMENT 'CREDIT RECORD STATUS',
  `CRU_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CRU_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CRU_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CRU_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CRU_ID`),
  CONSTRAINT `FK_CK_CREDIT_UPDATE_CK_MST_CREDIT_UPDATE_STATE` FOREIGN KEY (`CRU_STATE`) REFERENCES `T_CK_MST_CREDIT_UPDATE_STATE` (`ST_ID`),
  CONSTRAINT `FK_CK_CREDIT_UPDATE_CK_MST_SERVICE_TYPE` FOREIGN KEY (`CRU_SERVICE_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_CREDIT_UPDATE_CORE_ACCN` FOREIGN KEY (`CRU_COMPANY`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CREDIT_UPDATE_MST_CURRENCY` FOREIGN KEY (`CRU_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CREDIT UPDATE TABLE';

