CREATE TABLE `T_CK_CT_JOB_TERM_REQ` (
  `JTR_ID` varchar(35) NOT NULL COMMENT 'JOB TERMINATION REQUEST ID - UUID',
  `JTR_ACCN` varchar(35) NOT NULL COMMENT 'CO COMPANY RELATED TO JOBS - REFERENCES T_CORE_ACCN:ACCN_ID',
  `JTR_CR_LIMIT` double(15,2) DEFAULT '0.00' COMMENT 'CREDIT AMOUNT',
  `JTR_CR_BAL` double(15,2) DEFAULT '0.00' COMMENT 'CREDIT BALANCE',
  `JTR_INV_OPEN` int DEFAULT 0 COMMENT 'NUMBER OF OPEN INVOICES',
  `JTR_AMT_OPEN` double(15,2) DEFAULT '0.00' COMMENT 'OUTSTANDING AM OUNT OF DN+INV',
  `JTR_DT_DUE_INV` datetime DEFAULT NULL COMMENT 'EARLIEST DUED INVOICE',
  `JTR_NO_JOBS` smallint DEFAULT 0 COMMENT 'NUMBER OF JOBS TO BE TERMINATED',
  `JTR_JOBS_PLTFEE_AMT` decimal(15,2) DEFAULT '0.00' COMMENT 'JOBS TOTAL PLATFORM FEE',
  `JTR_JOBS_DN_AMT` decimal(15,2) DEFAULT '0.00' COMMENT 'JOBS TOTAL DN FEE',
  `JTR_JOBS_DEFAULT` decimal(15,2) DEFAULT '0.00' COMMENT 'JOBS TOTAL DEFAULTED',
  `JTR_UID_REQUESTOR` varchar(35) DEFAULT NULL COMMENT 'UID REQUESTOR',
  `JTR_COMMENT_REQUESTOR` mediumtext DEFAULT NULL COMMENT 'REQUESTOR COMMENT',
  `JTR_DT_SUBMIT` datetime DEFAULT NULL COMMENT 'DATE OF SUMBISSION',
  `JTR_UID_APPROVER` varchar(35) DEFAULT NULL COMMENT 'UID APPROVER',
  `JTR_COMMENT_APPROVER` mediumtext DEFAULT NULL COMMENT 'APPROVER COMMENT',
  `JTR_DT_APPROVE_REJECT` datetime DEFAULT NULL COMMENT 'DATE OF APPROVAL OR REJECTION',
  `JTR_COMMENT` mediumtext DEFAULT NULL COMMENT 'COMMENT FOR THE REJECTION',
  `JTR_STATUS` char(1) DEFAULT NULL COMMENT 'RATE TABLE REJECT STATE STATUS',
  `JTR_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JTR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JTR_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JTR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JTR_ID`),
  CONSTRAINT `FK_CK_CT_JOB_TERM_CORE_ACCN` FOREIGN KEY (`JTR_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB TERMINATION REQUEST TABLE';


CREATE TABLE `T_CK_CT_JOB_TERM` (
  `JT_ID` varchar(35) NOT NULL COMMENT 'JOB TERMINATION ID - UUID',
  `JT_REQ` varchar(35) NOT NULL COMMENT 'TERMINATION REQUEST - REFERENCES T_CK_CT_JOB_TERM_REQ:JTR_ID',
  `JT_JOB` varchar(35) NOT NULL COMMENT 'TERMINATION REQUEST - REFERENCES T_CK_JOB_TRUCK:JOB_ID',
  `JT_JOB_DN` double(15,2) DEFAULT '0.00' COMMENT 'DN AMOUNT',
  `JT_JOB_PLTFEE_AMT_COFF` double(15,2) DEFAULT '0.00' COMMENT 'COFF PLATFORM FEE AMOUNT',
  `JT_JOB_PLTFEE_AMT_TO` double(15,2) DEFAULT '0.00' COMMENT 'TO PLATFORM FEE AMOUNT',
  `JT_STATUS` char(1) DEFAULT NULL COMMENT 'RATE TABLE REJECT STATE STATUS',
  `JT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `JT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `JT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `JT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`JT_ID`),
  CONSTRAINT `FK_CK_CT_JOB_TERM_CK_CT_JOB_TERM_REQ` FOREIGN KEY (`JT_REQ`) REFERENCES `T_CK_CT_JOB_TERM_REQ` (`JTR_ID`),
  CONSTRAINT `FK_CK_CT_JOB_TERM_CK_JOB_TRUCK` FOREIGN KEY (`JT_JOB`) REFERENCES `T_CK_JOB_TRUCK` (`JOB_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='JOB TERMINATION TABLE';


