CREATE TABLE `T_CK_ACCN_ATT` (
  `AAT_ID` varchar(35) NOT NULL COMMENT 'ACCOUNT ATTACHED ID  - UUID',
  `AAT_ACCN` varchar(35) NOT NULL COMMENT 'ACCOUNT FOR THE ATTACHMENT - REFERENCES T_CORE_ACCN:ACCN_ID',
  `AAT_TYPE_ID` varchar(35) NOT NULL COMMENT 'ATTACHMENT TYPE ID  -  REFERENCE T_CK_MST_ACCN_ATT_TYPE:AT_ID',
  `AAT_TYPE_WORKFLOW` varchar(35) NOT NULL COMMENT 'WORKFLOW TYPE ID  - REFERENCE T_CK_MST_ACCN_ATT_TYPE:AT_WORKFLOW',  
  `AAT_NAME` varchar(256) DEFAULT NULL COMMENT 'SHORT NAME FOR TYPE OF PROCESS TYPE.',
  `AAT_NO` varchar(256) DEFAULT NULL COMMENT 'ATTACHMENT NUMBER',  
  `AT_DT_VALIDILITY` datetime DEFAULT NULL COMMENT 'VALIDILITY DATE OF ATTACHMENT',
  `AAT_LOC` varchar(1024) DEFAULT NULL COMMENT 'RELATIVE PATH NAME TO THE LOCATION OF THE ATTACHMENT',  
  `AT_STATUS` char(1) DEFAULT NULL COMMENT 'STATUS OF THE ATTACHMENT',
  `AT_DT_CREATE` datetime DEFAULT NULL COMMENT 'CREATED DATE',
  `AT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'CREATED BY UID',
  `AT_DT_LUPD` datetime DEFAULT NULL COMMENT 'UPDATED DATE',
  `AT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'UPDATED BY UID',
  PRIMARY KEY (`AAT_ID`),
  CONSTRAINT `FK_CK_ACCN_ATT_CORE_ACCN` FOREIGN KEY (`AAT_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_ACCN_ATT_CK_MST_ACCN_ATT_TYPE` FOREIGN KEY (`AAT_TYPE_ID`, `AAT_TYPE_WORKFLOW`) REFERENCES `T_CK_MST_ACCN_ATT_TYPE` (`AT_ID`,`AT_WORKFLOW`)  
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT = 'CK ACCN WORKFLOW ATTACHMENT TABLE';

