  `RT_DT_LUPD` datetime DEFAULT NULL COMMENT 'UPDATED DATE',
  `RT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'UPDATED BY UID',
  PRIMARY KEY (`RT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT = 'CK REMARK TYPE TABLE';


