CREATE TABLE `T_CK_CT_CONTRACT_REQ` (
  `CR_ID` varchar(35) NOT NULL COMMENT 'CONTRACT REQUEST ID - UUID',
  `CR_STATE` varchar(35) NOT NULL COMMENT 'CONTRACT REQUEST STATE - REFERENCE T_CK_CT_MST_CONTRACT_REQ_STATE:ST_ID',
  `CR_NAME` varchar(1024) DEFAULT NULL COMMENT 'RATE TABLE NAME',
  `CR_DESCRIPTION` mediumtext COMMENT 'RATE TABLE NAME',
  `CR_CCY` varchar(3) DEFAULT NULL COMMENT 'CONTRACT CURRENCY - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `CR_DT_START` datetime DEFAULT NULL COMMENT 'CONTRACT VALIDITY START',
  `CR_DT_END` datetime DEFAULT NULL COMMENT 'CONTRACT VALIDITY END',
  `CR_TO` varchar(35) DEFAULT NULL COMMENT 'CONTRACT TRUCK OPERATOR - REFERENCES T_CORE_ACCN:ACCN_ID',
  `CR_CHARGE_TO` varchar(35) DEFAULT NULL COMMENT 'CONTRACT TRUCK OPERATOR CHARGE - REFERENCES T_CK_CT_CONTRACT_REQ_CHARGE:CONC_ID',
  `CR_PAYTERM_TO` int DEFAULT NULL,
  `CR_CO_FF` varchar(35) DEFAULT NULL COMMENT 'CONTRACT CARGO OWNER - REFERENCES T_CORE_ACCN:ACCN_ID',
  `CR_CHARGE_CO_FF` varchar(35) DEFAULT NULL COMMENT 'CONTRACT CARGO OWNER CHARGE - REFERENCES T_CK_CT_CONTRACT_REQ_CHARGE:CONC_ID',
  `CR_PAYTERM_CO_FF` int DEFAULT NULL,
  `CR_UID_REQUESTOR` varchar(35) DEFAULT NULL COMMENT 'UID REQUESTOR',
  `CR_COMMENT_REQUESTOR` mediumtext DEFAULT NULL COMMENT 'REQUESTOR COMMENT',
  `CR_DT_SUBMIT` datetime DEFAULT NULL COMMENT 'DATE OF SUMBISSION',
  `CR_UID_APPROVER` varchar(35) DEFAULT NULL COMMENT 'UID APPROVER',
  `CR_COMMENT_APPROVER` mediumtext DEFAULT NULL COMMENT 'APPROVER COMMENT',
  `CR_DT_APPROVE_REJECT` datetime DEFAULT NULL COMMENT 'DATE OF APPROVAL OR REJECTION',
  `CR_COMMENT` mediumtext DEFAULT NULL COMMENT 'COMMENT FOR THE REJECTION',
  `CR_STATUS` char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  `CR_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CR_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CR_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CR_ID`),
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_CK_CT_MST_CONTRACT_REQ_STATE` FOREIGN KEY (`CR_STATE`) REFERENCES `T_CK_CT_MST_CONTRACT_REQ_STATE` (`ST_ID`),  
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_CK_CT_CONTRACT_REQ_CHARGE1` FOREIGN KEY (`CR_CHARGE_TO`) REFERENCES `T_CK_CT_CONTRACT_CHARGE` (`CONC_ID`),
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_CK_CT_CONTRACT_REQ_CHARGE2` FOREIGN KEY (`CR_CHARGE_CO_FF`) REFERENCES `T_CK_CT_CONTRACT_CHARGE` (`CONC_ID`),
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_CORE_ACCN1` FOREIGN KEY (`CR_TO`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_CORE_ACCN2` FOREIGN KEY (`CR_CO_FF`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_CT_CONTRACT_REQ_MST_CURRENCY` FOREIGN KEY (`CR_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CONTRACT REQUEST TABLE';


