CREATE TABLE `T_CK_CT_TRACK_LOC` (
  TL_ID varchar(35) NOT NULL COMMENT 'TRACK LOCATION ID - UUID',
  TL_JOB_ID varchar(35) NOT NULL COMMENT 'JOB_ID - REFERENCE T_CK_JOB_TRUCK:JOB_ID',
  TL_IMEI varchar(128) DEFAULT NULL COMMENT 'IMEI',
  TL_DT_START datetime DEFAULT NULL COMMENT 'CALL ASCENT API URL: REQUEST START TIME PARAMETER',
  TL_DT_END datetime DEFAULT NULL COMMENT 'CALL ASCENT API URL: REQUEST END TIME PARAMETER',
  TL_REQ_URL varchar(1024) DEFAULT '' COMMENT 'CALL ASCENT API REQUEST URL',
  TL_RSP_BODY mediumtext DEFAULT NULL COMMENT 'CALL ASCENT API RESPONSE BODY',
  TL_REMARK varchar(1024) DEFAULT '' COMMENT 'REMARK',
  TL_STATUS char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  TL_DT_CREATE datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  TL_UID_CREATE varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  TL_DT_LUPD datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  TL_UID_LUPD varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TL_ID`),
  CONSTRAINT `FK_T_CK_CT_TRACK_LOC_JOB_TRUCK` FOREIGN KEY (`TL_JOB_ID`) REFERENCES `T_CK_JOB_TRUCK` (`JOB_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TRACK AND TRACE LOCATION TABLE';


CREATE TABLE `T_CK_CT_TRACK_LOC_ITEM` (
  TLI_ID varchar(35) NOT NULL COMMENT 'TRACK LOCATION ITEM ID - UUID',
  TLI_TRACK_LOC_ID varchar(35) NOT NULL COMMENT 'TRACK_LOC_ID - REFERENCE T_CK_CT_TRACK_LOC:TL_ID',
  TLI_LOC_ID varchar(35) DEFAULT NULL COMMENT 'LOC_ID - REFERENCE T_CK_CT_LOCATION:LOC_ID',
  TLI_GPS varchar(128) NOT NULL COMMENT 'FROM ASCENT API RESPONSE BODY',
  TLI_RADIUS int NOT NULL COMMENT 'RADIUS:10,30,100',
  TLI_DT_ENTER datetime DEFAULT NULL COMMENT 'ENTER TIME',
  TLI_DT_EXIT datetime DEFAULT NULL COMMENT 'EXIT TIME',
  TLI_STATUS char(1) DEFAULT NULL COMMENT 'CONTRACT STATE STATUS',
  TLI_DT_CREATE datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  TLI_UID_CREATE varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  TLI_DT_LUPD datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  TLI_UID_LUPD varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TLI_ID`),
  CONSTRAINT `FK_T_CK_CT_TRACK_LOC_ITEM_TRACK_LOC_ID` FOREIGN KEY (`TLI_TRACK_LOC_ID`) REFERENCES `T_CK_CT_TRACK_LOC` (`TL_ID`),
  CONSTRAINT `FK_T_CK_CT_TRACK_LOC_ITEM_TL_ID` FOREIGN KEY (`TLI_LOC_ID`) REFERENCES `T_CK_CT_LOCATION` (`LOC_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='TRACK AND TRACE LOCATION ITEM TABLE';


